import{_ as e,c as l,o as n,a3 as r}from"./chunks/framework.BusRvirq.js";const y=JSON.parse('{"title":"사용자 인수 테스트(UAT) 완료 확인서 (UAT Sign-off)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/09_UAT_Signoff_template.html"}]]},"headers":[],"relativePath":"public/templates/09_UAT_Signoff_template.md","filePath":"public/templates/09_UAT_Signoff_template.md","lastUpdated":1790810085000}'),s={name:"public/templates/09_UAT_Signoff_template.md"};function a(d,t,g,i,o,c){return n(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="사용자-인수-테스트-uat-완료-확인서-uat-sign-off" tabindex="-1">사용자 인수 테스트(UAT) 완료 확인서 (UAT Sign-off) <a class="header-anchor" href="#사용자-인수-테스트-uat-완료-확인서-uat-sign-off" aria-label="Permalink to “사용자 인수 테스트(UAT) 완료 확인서 (UAT Sign-off)”">​</a></h1><p>본 문서는 [발주회사명] (이하 &quot;발주처&quot;라 한다)과 주식회사 엠파시 (이하 &quot;수행사&quot;라 한다)가 공동으로 수행한 [프로젝트명]의 <strong>사용자 인수 테스트(User Acceptance Test: UAT)</strong> 수행 결과를 평가하고, 테스트 합격 판정 및 상용 운영 오픈 승인을 위해 작성하는 공식 확인서입니다.</p><hr><h3 id="_1-테스트-개요" tabindex="-1">1. 테스트 개요 <a class="header-anchor" href="#_1-테스트-개요" aria-label="Permalink to “1. 테스트 개요”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명</strong></td><td style="text-align:left;">[계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>테스트 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일 (총 [ ] 일간)</td></tr><tr><td style="text-align:left;"><strong>테스트 장소 / 환경</strong></td><td style="text-align:left;">[발주처 테스트실 / 스테이징(Staging) 환경]</td></tr><tr><td style="text-align:left;"><strong>테스트 참여자</strong></td><td style="text-align:left;">발주처 현업 부서 테스터 [ ] 명, 수행사 지원 인력 [ ] 명</td></tr><tr><td style="text-align:left;"><strong>대상 테스트 시나리오</strong></td><td style="text-align:left;">총 [ ] 개 비즈니스 업무 시나리오 (총 [ ] 개 세부 테스트 케이스)</td></tr></tbody></table><hr><h3 id="_2-테스트-수행-결과-및-시나리오-통과율" tabindex="-1">2. 테스트 수행 결과 및 시나리오 통과율 <a class="header-anchor" href="#_2-테스트-수행-결과-및-시나리오-통과율" aria-label="Permalink to “2. 테스트 수행 결과 및 시나리오 통과율”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">업무 구분</th><th style="text-align:center;">시나리오 수</th><th style="text-align:center;">성공 건수 (Pass)</th><th style="text-align:center;">조건부 성공</th><th style="text-align:center;">실패 건수 (Fail)</th><th style="text-align:center;">최종 통과율 (%)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>회원 및 권한 관리</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>핵심 업무 프로세스 1</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>핵심 업무 프로세스 2</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>대외 기관 연계 인터페이스</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>통계 / 리포트 / 엑셀</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:center;"><strong>[ ] 개</strong></td><td style="text-align:center;"><strong>[ ] 개</strong></td><td style="text-align:center;"><strong>0</strong></td><td style="text-align:center;"><strong>0</strong></td><td style="text-align:center;"><strong>100.0%</strong></td></tr></tbody></table><hr><h3 id="_3-결함-defect-조치-및-조치-완료율" tabindex="-1">3. 결함(Defect) 조치 및 조치 완료율 <a class="header-anchor" href="#_3-결함-defect-조치-및-조치-완료율" aria-label="Permalink to “3. 결함(Defect) 조치 및 조치 완료율”">​</a></h3><ul><li>결함 등급 정의: <ul><li><strong>치명적 (Blocker / Critical)</strong>: 시스템 정지, 데이터 유실, 핵심 결제/정산 오류</li><li><strong>주요 (Major)</strong>: 주요 기능 오동작이나 우회 경로 존재</li><li><strong>경미 (Minor / Trivial)</strong>: 오탈자, 단순 UI 레이아웃 미세 정렬 등</li></ul></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">결함 등급</th><th style="text-align:center;">접수 건수</th><th style="text-align:center;">조치 완료 건수</th><th style="text-align:center;">오픈 후 조치 합의 건수</th><th style="text-align:center;">잔여 미해결 건수</th><th style="text-align:center;">조치율 (%)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>치명적 (Critical)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">0 건</td><td style="text-align:center;"><strong>0 건</strong></td><td style="text-align:center;"><strong>100.0% (필수)</strong></td></tr><tr><td style="text-align:left;"><strong>주요 (Major)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">0 건</td><td style="text-align:center;"><strong>0 건</strong></td><td style="text-align:center;"><strong>100.0% (필수)</strong></td></tr><tr><td style="text-align:left;"><strong>경미 (Minor)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">0 건</td><td style="text-align:center;">100.0%</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:center;"><strong>0 건</strong></td><td style="text-align:center;"><strong>100.0%</strong></td></tr></tbody></table><ul><li>경미한 결함 중 오픈 후 안정화 기간(오픈 후 14일 이내)에 패치하기로 합의한 항목은 별첨 1 &quot;잔여 조치 목록&quot;에 명시함.</li></ul><hr><h3 id="_4-사용자-인수-테스트-종합-판정" tabindex="-1">4. 사용자 인수 테스트 종합 판정 <a class="header-anchor" href="#_4-사용자-인수-테스트-종합-판정" aria-label="Permalink to “4. 사용자 인수 테스트 종합 판정”">​</a></h3><ol><li><strong>테스트 수용 기준(Acceptance Criteria) 충족 여부</strong>: <ul><li>치명적/주요 결함 잔여 0건 달성: <strong>[ 충족 ]</strong></li><li>시나리오 통과율 98% 이상 달성: <strong>[ 충족 ]</strong></li><li>성능/부하 테스트 (동시접속자 [ ]명, 평균 응답속도 [ 1.2 ]초 이내): <strong>[ 충족 ]</strong></li></ul></li><li><strong>최종 판정</strong>: <ul><li>[ ] <strong>합격 (Acceptance Passed)</strong>: 신규 시스템의 상용 운영 오픈(Go-Live)을 승인함.</li><li>[ ] <strong>조건부 합격 (Conditional)</strong>: 지정된 기한 내 잔여 결함 패치 완료 후 오픈.</li><li>[ ] <strong>불합격 (Rejected)</strong>: 치명적 결함 미해결로 재테스트 실시.</li></ul></li></ol><hr><p>위와 같이 사용자 인수 테스트(UAT)가 성공적으로 완료되었음을 확인하며, 신규 시스템의 상용 배포 및 가동에 공식 동의합니다.</p><p><strong>판정일자: 202 년 월 일</strong></p><p><strong>[발주처 현업 테스터 대표]</strong></p><ul><li>소속 부서: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[발주처 사업 총괄 책임자]</strong></p><ul><li>소속 부서: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[수행사 프로젝트 관리자 (PM)]</strong></p><ul><li>소속: 주식회사 엠파시</li><li>직급: [ ] 성명: [ ] (서명)</li></ul>',25)])])}const h=e(s,[["render",a]]);export{y as __pageData,h as default};
